<body>
<div id="game">
  <div class="header">
    <span class="station-name">VICTORIA <strong>DISPATCH</strong> CONTROL</span>
    <span class="station-name" style="font-size:11px;">MISS <strong id="miss-limit-label">0/5</strong> &rarr; STATION CLOSED</span>
  </div>

  <div class="hud">
    <div class="stat">
      <span class="stat-label">Score</span>
      <span class="stat-val" id="score-val">0</span>
    </div>
    <div class="stat">
      <span class="stat-label">Routed</span>
      <span class="stat-val" id="routed-val">0</span>
    </div>
    <div class="stat">
      <span class="stat-label">Missed</span>
      <span class="stat-val" id="missed-val" style="color:var(--red)">0</span>
    </div>
    <div class="urgency-wrap">
      <span class="urgency-label">Most urgent TTL</span>
      <div id="timer-bar-track"><div id="timer-bar"></div></div>
    </div>
    <div class="level-badge">
      <span class="stat-label">Level</span>
      <span class="stat-val" id="level-val" style="color:var(--blue);font-size:18px;">1</span>
    </div>
  </div>

  <div style="position:relative;">
    <div class="section-row">
      <span class="section-title">Arrivals</span>
      <span class="section-line"></span>
      <span class="section-hint">click train &rarr; click platform</span>
    </div>
    <div id="arrivals-area"></div>

    <div class="section-row">
      <span class="section-title">Platforms</span>
      <span class="section-line"></span>
    </div>
    <div id="platforms-area">
      <div class="platform" id="plat-0" data-idx="0"><div class="plat-num">Platform 1</div><div class="plat-empty">&mdash; empty &mdash;</div></div>
      <div class="platform" id="plat-1" data-idx="1"><div class="plat-num">Platform 2</div><div class="plat-empty">&mdash; empty &mdash;</div></div>
      <div class="platform" id="plat-2" data-idx="2"><div class="plat-num">Platform 3</div><div class="plat-empty">&mdash; empty &mdash;</div></div>
    </div>

    <div id="log"></div>

    <div id="screen-over">
      <span class="over-tag">Station closed</span>
      <div class="over-title" id="over-title">Too many misses</div>
      <div class="over-score" id="over-score">0 <small>pts</small></div>
      <div class="over-stats" id="over-stats"></div>
      <button class="play-btn" onclick="startGame()">New shift</button>
    </div>
  </div>
</div>

<script>
const DESTS = ['Edinburgh Waverley','Bristol Temple Meads','Leeds Central','Brighton','Oxford Parkway','York','Bath Spa','Cardiff Central','Derby Midland','Exeter St Davids'];
const TYPES = ['EXP','LCL','REG','ITC','SHT'];
const MAX_MISSED = 5;
const PLATFORM_DWELL = 8000;

let trains, platforms, selected, score, routed, missed, level;
let spawnTimer, levelTimer, loopId, lastTick, clearTimers;

function uid() {
  const L = 'ABCDEFGHJKLMNPQRSTUVWXYZ', D = '0123456789';
  return L[Math.random()*L.length|0] + L[Math.random()*L.length|0] + D[Math.random()*D.length|0] + D[Math.random()*D.length|0];
}
function rnd(a) { return a[Math.random()*a.length|0]; }
function urgColor(f) { return f < 0.25 ? 'var(--red)' : f < 0.55 ? 'var(--amber)' : 'var(--green)'; }

function spawnTrain() {
  const maxTtl = Math.max(6, 16 - (level - 1) * 1.1);
  trains.push({ id: uid(), dest: rnd(DESTS), type: rnd(TYPES), ttl: maxTtl, maxTtl });
}

function renderArrivals() {
  const area = document.getElementById('arrivals-area');
  area.innerHTML = '';
  if (!trains.length) {
    const d = document.createElement('div');
    d.className = 'no-trains';
    d.textContent = '\u2014 awaiting incoming services \u2014';
    area.appendChild(d);
    return;
  }
  trains.forEach(t => {
    const frac = Math.max(0, t.ttl / t.maxTtl);
    const col = urgColor(frac);
    const isSel = selected === t.id;
    const card = document.createElement('div');
    card.className = 'train-card' + (isSel ? ' selected' : '') + (frac < 0.25 && !isSel ? ' urgent-pulse' : '');
    card.innerHTML =
      '<div class="train-id"><span class="dot" style="background:' + col + '"></span>' + t.type + ' ' + t.id + '</div>' +
      '<div class="train-dest">\u2192 <span>' + t.dest + '</span></div>' +
      '<div class="ttl-track"><div class="ttl-fill" style="width:' + (frac*100) + '%;background:' + col + '"></div></div>';
    card.onclick = () => selectTrain(t.id);
    area.appendChild(card);
  });
}

function selectTrain(id) {
  selected = selected === id ? null : id;
  renderArrivals();
  renderPlatforms();
}

function renderPlatforms() {
  platforms.forEach((p, i) => {
    const el = document.getElementById('plat-' + i);
    const empty = !p.train;
    el.className = 'platform' + (!empty ? ' busy' : (selected ? ' accepting' : ''));
    if (!empty) {
      const frac = Math.max(0, p.dwellLeft / PLATFORM_DWELL);
      el.innerHTML =
        '<div class="plat-num">Platform ' + (i+1) + '</div>' +
        '<div class="plat-train-id">' + p.train.type + ' ' + p.train.id + '</div>' +
        '<div class="plat-train-dest">\u2192 <span>' + p.train.dest + '</span></div>' +
        '<div class="plat-dwell-track"><div class="plat-dwell-fill" style="width:' + (frac*100) + '%"></div></div>' +
        '<div class="plat-clear-label">' + Math.ceil(p.dwellLeft/1000) + 's</div>';
    } else {
      el.innerHTML = '<div class="plat-num">Platform ' + (i+1) + '</div><div class="plat-empty">\u2014 empty \u2014</div>';
    }
  });
}

function assignToPlatform(idx) {
  if (!selected) return;
  if (platforms[idx].train) { addLog('Platform ' + (idx+1) + ' occupied.', 'log-line'); return; }
  const t = trains.find(x => x.id === selected);
  if (!t) { selected = null; renderArrivals(); renderPlatforms(); return; }
  trains = trains.filter(x => x.id !== selected);
  platforms[idx].train = t;
  platforms[idx].dwellLeft = PLATFORM_DWELL;
  const pts = 10 + Math.round((t.ttl / t.maxTtl) * 20) + level * 2;
  score += pts;
  routed++;
  addLog(t.type + ' ' + t.id + ' \u2192 Platform ' + (idx+1) + '  +' + pts + 'pts', 'log-line ok');
  selected = null;
  updateHUD();
  renderArrivals();
  if (clearTimers[idx]) clearTimeout(clearTimers[idx]);
  clearTimers[idx] = setTimeout(() => {
    platforms[idx].train = null;
    platforms[idx].dwellLeft = 0;
    addLog('Platform ' + (idx+1) + ' cleared.', 'log-line');
    renderPlatforms();
  }, PLATFORM_DWELL);
}

document.querySelectorAll('.platform').forEach(el => {
  el.addEventListener('click', () => assignToPlatform(parseInt(el.dataset.idx)));
});

function addLog(msg, cls) {
  const log = document.getElementById('log');
  const line = document.createElement('div');
  line.className = (cls || 'log-line') + ' fresh';
  line.textContent = msg;
  log.prepend(line);
  setTimeout(() => line.classList.remove('fresh'), 1200);
  while (log.children.length > 3) log.removeChild(log.lastChild);
}

function updateHUD() {
  document.getElementById('score-val').textContent = score;
  document.getElementById('routed-val').textContent = routed;
  document.getElementById('missed-val').textContent = missed;
  document.getElementById('level-val').textContent = level;
  document.getElementById('miss-limit-label').textContent = missed + '/' + MAX_MISSED;
}

function tick(ts) {
  if (!loopId) return;
  if (!lastTick) lastTick = ts;
  const dt = Math.min(ts - lastTick, 200);
  lastTick = ts;

  spawnTimer -= dt;
  levelTimer += dt;

  const spawnInterval = Math.max(2200, 5800 - (level - 1) * 380);
  if (spawnTimer <= 0 && trains.length < 7) {
    spawnTrain();
    spawnTimer = spawnInterval + (Math.random() - 0.5) * 800;
  }
  if (levelTimer >= 30000) {
    level++;
    levelTimer = 0;
    addLog('Level ' + level + ' \u2014 faster arrivals, shorter TTL.', 'log-line fresh');
    updateHUD();
  }

  const dtSec = dt / 1000;
  trains.forEach(t => { t.ttl = Math.max(0, t.ttl - dtSec); });

  const expired = trains.filter(t => t.ttl <= 0);
  expired.forEach(t => {
    missed++;
    score = Math.max(0, score - 15);
    addLog('MISSED: ' + t.type + ' ' + t.id + ' to ' + t.dest + '  \u221215pts', 'log-line bad');
    if (selected === t.id) selected = null;
  });
  trains = trains.filter(t => t.ttl > 0);
  if (expired.length) updateHUD();

  platforms.forEach(p => { if (p.train) p.dwellLeft = Math.max(0, p.dwellLeft - dt); });

  if (missed >= MAX_MISSED) { endGame(); return; }

  const bar = document.getElementById('timer-bar');
  if (trains.length) {
    const minFrac = Math.min(...trains.map(t => t.ttl / t.maxTtl));
    bar.style.width = (minFrac * 100) + '%';
    bar.style.background = urgColor(minFrac);
  } else {
    bar.style.width = '100%';
    bar.style.background = 'var(--green)';
  }

  renderArrivals();
  renderPlatforms();
  loopId = requestAnimationFrame(tick);
}

function endGame() {
  loopId = null;
  clearTimers.forEach(t => t && clearTimeout(t));
  document.getElementById('over-score').innerHTML = score + ' <small>pts</small>';
  document.getElementById('over-title').textContent = missed >= MAX_MISSED ? 'Station overwhelmed' : 'Shift complete';
  document.getElementById('over-stats').innerHTML =
    'Trains routed: <strong>' + routed + '</strong><br>' +
    'Trains missed: <strong>' + missed + '</strong><br>' +
    'Level reached: <strong>' + level + '</strong>';
  document.getElementById('screen-over').classList.add('show');
}

function startGame() {
  trains = []; platforms = [{},{},{}]; selected = null;
  score = 0; routed = 0; missed = 0; level = 1;
  spawnTimer = 0; levelTimer = 0; lastTick = null;
  clearTimers = [null, null, null];
  loopId = null;
  document.getElementById('screen-over').classList.remove('show');
  document.getElementById('log').innerHTML = '';
  updateHUD();
  renderArrivals();
  renderPlatforms();
  addLog('Shift started. Route incoming services.', 'log-line fresh');
  loopId = true;
  loopId = requestAnimationFrame(tick);
}

startGame();
</script>
</body>
